// AM pick_tickets -> canonical PickTicket[], enriched with per-SKU UPC and
// full color name from Inventory (pick_ticket_items alone only has color
// code + size, no UPC -- same combine pattern as parseItem.js). Falls back
// to a realistic sample if AM has none yet (nothing released/picked in the
// test company). Mirrors adapters/erp/apparelmagic/lib/parsePickTicket.js --
// keep in sync if that file changes.
const num = (v) => (v == null || v === '' ? null : Number(v));
const resp = $('Get AM Pick Tickets').first().json.response || [];
const skus = $('Get AM Inventory (SKUs)').first().json.response || [];
const skusById = {};
for (const sku of skus) { skusById[sku.sku_id] = sku; }

const records = resp.length ? resp : [{
  pick_ticket_id: 'SAMPLE-3000', order_id: null, customer_id: '1', customer_po: 'PO6979505951736416',
  warehouse_id: '1', date: new Date().toISOString().slice(0,10), date_due: null,
  ship_to_name: 'Best Store Ever', address_1: '111 Main Street', address_2: null,
  city: 'West Palm Beach', state: 'FL', postal_code: '33405', country: 'USA',
  ship_via: null, tracking_number: null, qty: '45', amount: '899.55',
  pick_ticket_items: [ { product_id: '4', sku_id: '4', attr_2: 'BLK', size: 'M100', style_number: 'JEAN1', description: 'Classic Denim Jean', qty: '45', unit_price: '19.99', amount: '899.55', is_taxable: '0' } ]
}];
const isSample = resp.length === 0;
// Sample fallback has no real Inventory match -- give it a plausible UPC/color
// name directly so the sample stays meaningful for testing.
if (isSample) { skusById['4'] = { sku_id: '4', attr_2: 'BLK', attr_2_name: 'Black', upc_display: '192731473731' }; }

return records.map((record) => ({ json: { isSample, pickTicket: {
  pickTicketId: record.pick_ticket_id, orderId: record.order_id || null, customerId: record.customer_id,
  customerPo: record.customer_po || null, warehouseId: record.warehouse_id || null,
  date: record.date_internal || record.date || null, dateDue: record.date_due_internal || record.date_due || null,
  shipTo: { name: record.ship_to_name || null, address1: record.address_1 || null, address2: record.address_2 || null, city: record.city || null, state: record.state || null, zip: record.postal_code || null, country: record.country || null },
  shipVia: record.ship_via || null, trackingNumber: record.tracking_number || null,
  qty: num(record.qty), amount: num(record.amount),
  lines: (record.pick_ticket_items || []).map((item) => {
    const sku = skusById[item.sku_id] || {};
    return {
      productId: item.product_id, skuId: item.sku_id,
      color: item.attr_2 || sku.attr_2 || null, colorName: sku.attr_2_name || null,
      size: item.size || sku.size || null, styleNumber: item.style_number || null,
      description: item.description || null, upc: sku.upc_display || sku.upc_11 || null,
      qty: num(item.qty), unitPrice: num(item.unit_price), amount: num(item.amount), isTaxable: item.is_taxable === '1',
    };
  }),
} } }));

// Ports adapters/edi/x12-dcg/lib/{envelope,itemCode,build940}.js into a
// single n8n Code node (Code nodes can't import repo files). Keep in sync
// with those files if the builder logic changes -- see
// adapters/edi/x12-dcg/schema-notes.md for the full field mapping and every
// open question flagged below. Runs once PER pick ticket -- unlike 888,
// each pick ticket is its own 940 shipment/transaction, not batched.
const ELEMENT_SEP = '|';
const SEGMENT_TERM = '\n';
function segment(...elements) { return elements.map((e) => (e ?? '')).join(ELEMENT_SEP); }
function pad15(value) { return String(value ?? '').padEnd(15, ' ').slice(0, 15); }

function buildEnvelope(cfg, bodySegments) {
  const {
    senderQualifier = 'ZZ', senderId, receiverQualifier = 'ZZ', receiverId,
    interchangeControlNumber, groupControlNumber, transactionSetControlNumber = '0001',
    functionalIdentifierCode, transactionSetIdentifierCode,
    responsibleAgencyCode = 'X', versionReleaseIndustryCode = '004010',
    interchangeControlVersion = '00401', usageIndicator = 'T', date = new Date(),
  } = cfg;
  const yy = String(date.getUTCFullYear()).slice(2);
  const mm = String(date.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(date.getUTCDate()).padStart(2, '0');
  const hh = String(date.getUTCHours()).padStart(2, '0');
  const min = String(date.getUTCMinutes()).padStart(2, '0');
  const isaDate = `${yy}${mm}${dd}`;
  const gsDate = `${date.getUTCFullYear()}${mm}${dd}`;
  const time = `${hh}${min}`;
  const isaControl = String(interchangeControlNumber).padStart(9, '0');
  const isa = segment('ISA', '00', pad15(''), '00', pad15(''), senderQualifier, pad15(senderId), receiverQualifier, pad15(receiverId), isaDate, time, 'U', interchangeControlVersion, isaControl, '0', usageIndicator, '>');
  const gs = segment('GS', functionalIdentifierCode, senderId, receiverId, gsDate, time, String(groupControlNumber), responsibleAgencyCode, versionReleaseIndustryCode);
  const st = segment('ST', transactionSetIdentifierCode, transactionSetControlNumber);
  const se = segment('SE', String(bodySegments.length + 2), transactionSetControlNumber);
  const ge = segment('GE', '1', String(groupControlNumber));
  const iea = segment('IEA', '1', isaControl);
  return [isa, gs, st, ...bodySegments, se, ge, iea].join(SEGMENT_TERM) + SEGMENT_TERM;
}

function vendorItemNumber(styleNumber, color, size) {
  return `${styleNumber ?? ''}${color ?? ''}${size ?? ''}`.toUpperCase().replace(/\s+/g, '');
}
function ccyymmdd(isoDate) { return isoDate ? isoDate.replace(/-/g, '') : null; }

function buildW05(pickTicket, { transactionTypeCode }) {
  return segment('W05', 'N', pickTicket.pickTicketId ?? '', pickTicket.customerPo ?? '', '', '', transactionTypeCode);
}
function buildN1BT({ customerName, customerNumber }) {
  const elements = ['N1', 'BT', customerName ?? ''];
  if (customerNumber) elements.push('92', customerNumber);
  return segment(...elements);
}
function buildShipToLoop(shipTo) {
  const segs = [segment('N1', 'ST', shipTo?.name ?? '')];
  if (shipTo?.address1) segs.push(segment('N3', shipTo.address1, shipTo.address2 ?? ''));
  if (shipTo?.city) segs.push(segment('N4', shipTo.city ?? '', shipTo.state ?? '', shipTo.zip ?? '', shipTo.country ?? ''));
  return segs;
}
function buildOrderN9(pickTicket) {
  return pickTicket.orderId ? [segment('N9', 'CO', pickTicket.orderId)] : [];
}
function buildG62(pickTicket) {
  const segs = [];
  const earliest = ccyymmdd(pickTicket.date);
  if (earliest) segs.push(segment('G62', '10', earliest));
  const cancel = ccyymmdd(pickTicket.dateDue);
  if (cancel) segs.push(segment('G62', '01', cancel));
  return segs;
}
function buildW66({ paymentMethod, carrierCode }) {
  return segment('W66', paymentMethod, 'M', '', '', carrierCode ?? '');
}
function buildLineSegments(line, index) {
  const segs = [
    segment('LX', String(index + 1)),
    segment('W01', String(line.qty ?? ''), 'EA', line.upc ?? '', 'VN', vendorItemNumber(line.styleNumber, line.color, line.size), '', '', 'EA'),
    segment('G69', line.description ?? ''),
  ];
  if (line.styleNumber) segs.push(segment('N9', 'IS', line.styleNumber, line.description ?? ''));
  if (line.size) segs.push(segment('N9', 'IZ', line.size));
  if (line.color) segs.push(segment('N9', 'VC', line.color, line.colorName ?? ''));
  return segs;
}
function build940(pickTicket, options = {}) {
  const { customerName, customerNumber, transactionTypeCode = '42', paymentMethod = 'PP', date = new Date(), envelope = {} } = options;
  const body = [
    buildW05(pickTicket, { transactionTypeCode }),
    buildN1BT({ customerName, customerNumber }),
    ...buildShipToLoop(pickTicket.shipTo),
    ...buildOrderN9(pickTicket),
    ...buildG62(pickTicket),
    buildW66({ paymentMethod, carrierCode: pickTicket.shipVia }),
  ];
  (pickTicket.lines ?? []).forEach((line, index) => { body.push(...buildLineSegments(line, index)); });
  body.push(segment('W76', String(pickTicket.qty ?? '')));
  return buildEnvelope({ functionalIdentifierCode: 'OW', transactionSetIdentifierCode: '940', ...envelope, date }, body);
}

const pickTicket = $json.pickTicket;
const custResp = $('Get AM Customer').first().json;
// Generic customer lookup (page_size 1, not filtered by pickTicket.customerId)
// -- same simplification as 850-inbound.json's "Get AM Customer" node; AM's
// customers/ endpoint filter-by-ID capability hasn't been confirmed. The
// real customer name for THIS pick ticket's customerId is not guaranteed to
// match until that's verified -- see schema-notes.md.
const customerName = custResp?.response?.[0]?.customer_name || '';
const customerNumber = pickTicket.customerId;

const now = new Date();
const controlNumber = Number(String(Date.now()).slice(-9));

const x12 = build940(pickTicket, {
  customerName,
  customerNumber,
  date: now,
  envelope: {
    senderId: 'SCLFOOTWEAR',  // TBD -- confirm exact ISA sender ID DCG expects for SCL
    receiverId: 'DCG',        // TBD -- confirm exact ISA receiver ID DCG expects for SCL
    interchangeControlNumber: controlNumber,
    groupControlNumber: controlNumber,
    usageIndicator: 'T', // TEST -- flip to 'P' only once DCG confirms this is a real send
  },
});

const fileName = `SCL_940_${String(pickTicket.pickTicketId).replace(/[^a-zA-Z0-9-]/g, '_')}_${now.toISOString().replace(/[:.]/g, '-')}.txt`;
const dedupeKey = `940|${pickTicket.pickTicketId}`;

return {
  json: {
    fileName, dedupeKey, correlationId: dedupeKey,
    pickTicketId: pickTicket.pickTicketId, customerId: pickTicket.customerId,
    docType: '940', direction: 'outbound', status: 'created',
    externalIds: JSON.stringify({ controlNumber, pickTicketId: pickTicket.pickTicketId, isSample: $json.isSample }),
  },
  binary: {
    data: { data: Buffer.from(x12, 'utf-8').toString('base64'), mimeType: 'text/plain', fileName },
  },
};

// Postgres nodes don't reliably pass through binary data from their input
// item, so pull the X12 file's binary back from Build 940 X12 by name, and
// merge in the correlation_id Claim & Log just produced (needed by Mark Sent).
const meta = $('Build 940 X12').item.json;
const claim = $json;
return {
  json: { ...meta, correlationId: claim.correlation_id },
  binary: $('Build 940 X12').item.binary,
};

// Normalize a failed item (from any node's error output) for the errors table.
const j = $json || {};
const err = j.error || {};
const ptId = j.pickTicketId || (j.pickTicket && j.pickTicket.pickTicketId) || null;
const correlationId = j.correlationId || j.dedupeKey || (ptId ? ('940|' + ptId) : 'unknown');
const rootCause = String(err.message || err.description || 'DCG 940 outbound failure').slice(0, 500);
const detail = JSON.stringify({ message: err.message || null, pickTicketId: ptId, stack: err.stack ? String(err.stack).slice(0, 1000) : null });
return { json: { correlationId, rootCause, detail } };

parameters.query:
INSERT INTO errors (correlation_id, root_cause, detail, retry_eligible)
VALUES ($1, $2, $3::jsonb, true)
RETURNING id, correlation_id;

