// Confirm the file actually landed at DCG. StartFileTransfer's 200 only means
// AWS ACCEPTED the request; ListFileTransferResults gives the real outcome.
// A throw here fails the execution, which fires the SCL: Error Alerts workflow
// and emails help@goodmove.xyz. (AWS x-amz-json-1.1 responses arrive as a raw
// string under $json.data -- see build-n8n-workflow skill gotcha #7.)
const body = JSON.parse($json.data);
const results = body.FileTransferResults || [];
if (results.length === 0) {
  throw new Error('DCG delivery NOT confirmed: no transfer results returned yet. Increase the Wait, or check the connector.');
}
const failed = results.filter((r) => r.StatusCode !== 'COMPLETED');
if (failed.length > 0) {
  const f = failed[0];
  throw new Error('DCG delivery FAILED: ' + (f.FailureCode || 'unknown') + ' - ' + (f.FailureMessage || '') + ' (file: ' + (f.FilePath || '?') + ')');
}
return $json; // all COMPLETED -> continue to Mark Sent
